            public void SuspendConfigMerge() { }
        }

        private class NetworkBufferSettings { }
        private class LimitedFixedBufferPool { }

        private enum TransferOption
        {
            KEYS,
            SLOTS
        }

        private class Sketch { }

        private class ClusterSession { }

        private class MigrateSession
        {
            protected ILogger logger;
            protected IClusterProvider clusterProvider;
            public MigrateSession(
                ClusterSession clusterSession,
                IClusterProvider clusterProvider,
                string targetAddress,
                int targetPort,
                string targetNodeId,
                string username,
                string passwd,
                string sourceNodeId,
                bool copyOption,
                bool replaceOption,
                int timeout,
                HashSet<int> slots,
                Sketch sketch,
                TransferOption transferOption)
            {
                this.clusterProvider = clusterProvider;
                this.logger = clusterProvider.loggerFactory.CreateLogger("MigrateSession");
            }

            public virtual Task<(bool Success, ReadOnlyMemory<byte> ErrorMessage)> TryStartMigrationTaskAsync()
            {
                // Simulate starting background task that calls BeginAsyncMigrationTaskAsync
                _ = BeginAsyncMigrationTaskAsync();
                return Task.FromResult((true, ReadOnlyMemory<byte>.Empty));
            }

            protected virtual Task BeginAsyncMigrationTaskAsync()
            {
                // Simulate the failure path that logs error
                logger.LogError("Failed to set local slots {slots} to migrate state", "1,2,3");
                return Task.CompletedTask;
            }

            private protected virtual bool TryPrepareLocalForMigration()
            {
                return true;
            }
        }

